const rows = items.map(function(i) { return i.json; });
const pending = rows.filter(function(r) { return r['상태'] === '대기중'; });
if (pending.length === 0) return [{ json: { found: false } }];
const row = pending[0];
return [{
  json: {
    found: true,
    메인키워드: row['메인 키워드'] || '',
    서브키워드: row['서브키워드'] || '',
    서브수: parseInt(row['서브키워드 수']) || 3,
    참조키워드: row['참조키워드'] || '',
    연결링크: row['연결링크'] || ''
  }
}];

const d = items[0].json;
const keyword = d.메인키워드;
const subKeywords = d.서브키워드;
const subCount = d.서브수;
const refKeyword = d.참조키워드;
const refLink = d.연결링크;

var category;
if (keyword.indexOf('요양') !== -1 || keyword.indexOf('돌봄') !== -1 || keyword.indexOf('건강') !== -1 || keyword.indexOf('질환') !== -1 || keyword.indexOf('치료') !== -1 || keyword.indexOf('병원') !== -1 || keyword.indexOf('의료') !== -1 || keyword.indexOf('운동') !== -1 || keyword.indexOf('영양') !== -1 || keyword.indexOf('복지') !== -1 || keyword.indexOf('등급') !== -1) {
  category = 'health';
} else if (keyword.indexOf('연금') !== -1 || keyword.indexOf('상속') !== -1 || keyword.indexOf('증여') !== -1 || keyword.indexOf('보험') !== -1 || keyword.indexOf('투자') !== -1 || keyword.indexOf('절세') !== -1 || keyword.indexOf('세금') !== -1 || keyword.indexOf('재테크') !== -1 || keyword.indexOf('재산') !== -1) {
  category = 'wealth';
} else if (keyword.indexOf('장례') !== -1 || keyword.indexOf('상조') !== -1 || keyword.indexOf('납골') !== -1 || keyword.indexOf('봉안') !== -1 || keyword.indexOf('추모') !== -1 || keyword.indexOf('묘지') !== -1) {
  category = 'funeral';
} else {
  category = 'wellbeing';
}
const author = '시니어라이프 편집팀';

const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const dateCompact = dateStr.replace(/-/g, '');
const slug = keyword
  .replace(/\s+/g, '-')
  .replace(/[^a-zA-Z0-9가-힣-]/g, '')
  .substring(0, 40) + '-' + dateCompact;

const systemPrompt = '[역할]\n'
  + '너는 50~70대 시니어 분들의 건강하고 풍요로운 노후 생활을 돕는 "따뜻하고 전문적인 시니어 라이프 케어 전문 에디터"야.\n'
  + '독자의 연령대를 고려하여, 마음을 편안하게 해주는 다정함과 깊이 있는 전문성을 동시에 갖춘 독창적인 정보성 칼럼을 작성해줘.\n\n'
  + '[글쓰기 원칙 - 5대 인간 중심 서술 원칙]\n\n'
  + '1. 한국인에게 가장 자연스러운 일상적 표현 사용\n'
  + '- 번역기나 사전에서 직역한 듯한 어색한 어투(예: "~를 염두에 두어야 합니다", "우리는 ~에 직면해 있습니다")를 철저히 배제해줘.\n'
  + '- 실제 이웃의 지혜로운 동년배가 차를 마시며 조곤조곤 경험을 나누어 주듯 자연스러운 한국어 구어체와 관용구를 활용해줘.\n\n'
  + '2. 따뜻하고 부드러운 어미 사용 (딱딱한 어투 금지)\n'
  + '- "~하십시오", "~입니다" 같은 사무적이고 군대식의 딱딱한 종결 어미는 절대 쓰지 마라.\n'
  + '- 대신, 시니어 독자분들이 존중받는 느낌을 받도록 "~해요", "~해보세요", "~편이지요", "~인 경우가 많답니다"와 같이 다정하고 품격 있는 경어체를 사용해줘.\n\n'
  + '3. 능동태 중심의 주체적 문장 작성\n'
  + '- 수동태 표현(예: "~가 치러집니다", "해결되어집니다", "당하게 됩니다") 대신, 행위의 주체가 명확히 살아있는 능동태(예: "장례를 치러요", "슬픔을 해결해요", "어려움을 겪어요")로 모든 문장을 구성해줘.\n\n'
  + '4. 호흡이 짧고 가독성 높은 문장 배치\n'
  + '- 한 문장에는 오직 하나의 생각(One Sentence, One Idea)만 담고, 문장이 조금이라도 길어지면 주저 없이 마침표를 찍어 두세 개의 짧은 문장으로 나누어줘.\n\n'
  + '5. "당신", "여러분" 호칭 전면 금지 및 자연스러운 생략\n'
  + '- 글을 읽는 독자를 지칭할 때 "당신", "여러분"이라는 호칭은 일절 사용하지 마라.\n'
  + '- 호칭이 꼭 필요할 때는 "우리", "부모님", "시니어 분들", "상주님" 등으로 대체하고, 주어나 호칭을 생략할 수 있는 곳에서는 과감히 생략해줘.\n\n'
  + '[출력 형식 규칙]\n'
  + '- 출력은 반드시 아래 5개 마커를 순서대로 포함할 것\n'
  + '- 마크다운 형식으로 작성 (HTML 태그 금지)\n'
  + '- 마커와 실제 내용 사이에 줄바꿈 없이 바로 내용 작성';

var refLinkInstruction = '';
if (refKeyword && refLink) {
  refLinkInstruction = '- 참조 링크도 본문 자연스러운 위치에 마크다운 형식으로 1회 삽입:\n'
    + '  [' + refKeyword + '](' + refLink + ')\n';
}

const userPrompt = '아래 조건으로 시니어 라이프 매거진 칼럼을 작성해줘.\n\n'
  + '[키워드 조건]\n'
  + '- 메인 키워드: ' + keyword + '\n'
  + '- 서브키워드: ' + subKeywords + '\n'
  + '- 서브키워드 각각 ' + subCount + '회 이상 자연스럽게 포함\n\n'
  + '[작성 지침]\n'
  + '- 상투적인 순서(1일 차, 2일 차 등)를 탈피하여, 독자가 가장 먼저 알고 대비해야 하는 \'실질적인 마음가짐과 현실적 대처법\' 위주로 서술\n'
  + '- H2 소제목 3개 이상, H3도 자유롭게 활용\n'
  +   + refLinkInstruction
  + '- 공백 제외 1,500자 이상\n\n'
  + '[출력 형식] 아래 5개 마커를 반드시 포함:\n'
  + '##TITLE##여기에 SEO 최적화 제목 (60자 이내)\n'
  + '##META##여기에 메타 디스크립션 (120자 이내, 메인키워드 포함)\n'
  + '##AISUMMARY##여기에 AI 요약 (2~3문장, 핵심 내용 압축)\n'
  + '##TAGS##여기에 태그 (쉼표 구분, 5~7개)\n'
  + '##MARKDOWN##여기에 본문 전체 마크다운';

const gptBody = {
  model: 'gpt-4o',
  max_tokens: 8000,
  temperature: 1.0,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{
  json: {
    keyword, subKeywords, subCount,
    category, author,
    refKeyword, refLink,
    slug, dateStr,
    gptBody
  }
}];

const gptResult = items[0].json;
const prevData = $('슬러그 생성 및 GPT 요청 준비').first().json;

const raw = gptResult.choices[0].message.content;

function extractMarker(text, marker) {
  var tag = '##' + marker + '##';
  var start = text.indexOf(tag);
  if (start === -1) return '';
  start = start + tag.length;
  var nextHash = text.indexOf('##', start);
  var end = nextHash === -1 ? text.length : nextHash;
  return text.substring(start, end).trim();
}

var title = extractMarker(raw, 'TITLE') || prevData.keyword + ' 시니어 가이드';
var metaDescription = extractMarker(raw, 'META') || prevData.keyword + ' 관련 시니어 전문 정보';
var aiSummary = extractMarker(raw, 'AISUMMARY') || '';
var tagsRaw = extractMarker(raw, 'TAGS') || prevData.keyword;
var markdownContent = extractMarker(raw, 'MARKDOWN') || raw;

var tags = tagsRaw.split(',').map(function(t) { return t.trim(); }).filter(function(t) { return t.length > 0; });
var charCount = markdownContent.replace(/\s/g, '').length;
var readingTime = Math.max(5, Math.ceil(charCount / 500));

var kw = prevData.keyword;
var imageDesc = '';

if (kw.indexOf('상조') !== -1 || kw.indexOf('장례') !== -1 || kw.indexOf('계약') !== -1) {
  imageDesc = 'A warm and professional consultation scene between a kind Korean funeral service advisor and an elderly Korean couple in their 60s, sitting at a bright clean office table. Soft natural light, calm and trustworthy atmosphere.';
} else if (kw.indexOf('노후') !== -1 || kw.indexOf('은퇴') !== -1 || kw.indexOf('준비') !== -1) {
  imageDesc = 'A healthy and happy Korean senior couple in their 60s-70s enjoying a peaceful afternoon walk in a sunlit park. Warm golden hour light, green trees, comfortable lifestyle.';
} else if (kw.indexOf('요양') !== -1 || kw.indexOf('돌봄') !== -1 || kw.indexOf('복지') !== -1) {
  imageDesc = 'A caring scene of a professional Korean caregiver gently assisting a graceful elderly Korean woman indoors. Bright clean home environment, warm and compassionate atmosphere.';
} else if (kw.indexOf('납골') !== -1 || kw.indexOf('봉안') !== -1 || kw.indexOf('추모') !== -1) {
  imageDesc = 'A serene and peaceful memorial garden with soft sunlight filtering through trees. Stone memorial plaques surrounded by flowers, calm and respectful atmosphere, no people.';
} else if (kw.indexOf('유언') !== -1 || kw.indexOf('상속') !== -1 || kw.indexOf('증여') !== -1) {
  imageDesc = 'An elderly Korean man in his 70s thoughtfully reviewing documents at a wooden desk by a window. Warm afternoon light, family photos in background, peaceful and dignified setting.';
} else if (kw.indexOf('건강') !== -1 || kw.indexOf('운동') !== -1 || kw.indexOf('영양') !== -1) {
  imageDesc = 'A vibrant Korean senior couple in their 60s doing light morning exercises outdoors. Fresh morning light, park setting with trees, energetic and healthy lifestyle.';
} else if (kw.indexOf('여행') !== -1 || kw.indexOf('취미') !== -1 || kw.indexOf('문화') !== -1) {
  imageDesc = 'A cheerful Korean senior couple in their 60s enjoying a cultural outing or leisure activity together. Bright colorful joyful atmosphere, active senior lifestyle.';
} else {
  imageDesc = 'A warm and content Korean senior couple in their 60s-70s sharing a peaceful moment at home over tea. Cozy interior, natural light, family warmth and comfort.';
}

var imageBody = {
  model: 'gpt-image-1',
  prompt: imageDesc + ' No text or letters in the image. Photorealistic style, high quality.',
  n: 1,
  size: '1536x1024',
  quality: 'medium'
};

return [{
  json: {
    title: title,
    metaDescription: metaDescription,
    aiSummary: aiSummary,
    tags: tags,
    markdownContent: markdownContent,
    readingTime: readingTime,
    keyword: prevData.keyword,
    slug: prevData.slug,
    dateStr: prevData.dateStr,
    category: prevData.category,
    author: prevData.author,
    imageBody: imageBody
  }
}];

const prevData = $('GPT 응답 파싱 및 이미지 요청 준비').first().json;
const imageData = $('gpt-image-1: 이미지 생성').first().json;

const imageFilename = prevData.slug + '.png';
const imagePath = '/images/' + imageFilename;

const tagsYaml = prevData.tags.map(function(t) {
  return '"' + t.replace(/"/g, "'") + '"';
}).join(', ');

const frontmatter = '---\n'
  + 'title: "' + prevData.title.replace(/"/g, "'") + '"\n'
  + 'description: "' + prevData.metaDescription.replace(/"/g, "'") + '"\n'
  + 'publishedDate: "' + prevData.dateStr + '"\n'
  + 'author: "' + prevData.author + '"\n'
  + 'tags: [' + tagsYaml + ']\n'
  + 'category: "' + prevData.category + '"\n'
  + 'aiSummary: "' + prevData.aiSummary.replace(/"/g, "'").replace(/\n/g, ' ') + '"\n'
  + 'readingTime: ' + prevData.readingTime + '\n'
  + 'image: "' + imagePath + '"\n'
  + '---\n\n';

const fullMarkdown = frontmatter + prevData.markdownContent;
const base64Content = Buffer.from(fullMarkdown, 'utf8').toString('base64');

const imageBase64 = imageData.data[0].b64_json;

const encodedImagePath = 'public%2Fimages%2F' + imageFilename;
const encodedFilePath = 'src%2Fcontent%2Fposts%2F' + prevData.slug + '.md';

return [{
  json: {
    title: prevData.title,
    slug: prevData.slug,
    filePath: 'src/content/posts/' + prevData.slug + '.md',
    fullMarkdown: fullMarkdown,
    base64Content: base64Content,
    imagePath: imagePath,
    imageFilename: imageFilename,
    imageBase64: imageBase64,
    encodedImagePath: encodedImagePath,
    encodedFilePath: encodedFilePath,
    keyword: prevData.keyword,
    dateStr: prevData.dateStr
  }
}];
